def comps2(a,bg):
    H,W=a.shape; seen=np.zeros_like(a,bool); out=[]
    for i in range(H):
        for j in range(W):
            if a[i,j]!=bg and not seen[i,j]:
                col=a[i,j]; st=[(i,j)]; seen[i,j]=1; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny,nx] and a[ny,nx]==col:
                                seen[ny,nx]=1; st.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                mask=tuple(sorted((y-min(ys),x-min(xs)) for y,x in cells))
                out.append((int(col),len(cells),(min(ys),min(xs),max(ys),max(xs)),mask))
    return out
